import{_ as a,c as s,a as e,o as t}from"./app-C1s5HV2F.js";const p={};function o(c,n){return t(),s("div",null,n[0]||(n[0]=[e(`<h1 id="data-types" tabindex="-1"><a class="header-anchor" href="#data-types"><span>Data Types</span></a></h1><p>In OM, numbers are the primary data type. They can be whole numbers e.g <code>10</code>, <code>500</code> or numbers with decimal points e.g <code>3.14</code>, <code>0.5</code>. While JavaScript has other data types e.g <strong>strings for text</strong> or <strong>booleans for true/false values</strong>, OM functions are designed for numerical calculations. If you try to include non-numbers, OM might convert them to <code>NaN</code> meaning it can&#39;t understand them or throw an error.</p><p>For example:</p><p>You can calculate an array of prices that contains both float and integer:</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code><span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> add <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&quot;openmadness&quot;</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">const</span> prices <span class="token operator">=</span> <span class="token function">add</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token number">24.99</span><span class="token punctuation">,</span> <span class="token number">12.50</span><span class="token punctuation">,</span> <span class="token number">5.00</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&quot;Numeric prices:&quot;</span><span class="token punctuation">,</span> prices<span class="token punctuation">.</span>data<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>What happens if you try to include a string?</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code><span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> add <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&quot;openmadness&quot;</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">const</span> mixedItems <span class="token operator">=</span> <span class="token function">add</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token number">10</span><span class="token punctuation">,</span> <span class="token string">&#39;apple&#39;</span><span class="token punctuation">,</span> <span class="token number">20</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&quot;Mixed data:&quot;</span><span class="token punctuation">,</span> mixedItems<span class="token punctuation">.</span>data<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// Output: [10, NaN, 20]</span></span>
<span class="line"><span class="token comment">// &#39;apple&#39; can&#39;t be converted to a number, so it becomes NaN.</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container note"><p class="hint-container-title">Note</p><p>For reliable results, always provide numbers to Openmadness arrays.</p></div>`,8)]))}const l=a(p,[["render",o]]),r=JSON.parse('{"path":"/tutorials/fundamentals/data-types.html","title":"Data Types","lang":"en-US","frontmatter":{"lang":"en-US","title":"Data Types","description":"Learn about the data types in OpenMadness library"},"headers":[],"git":{"updatedTime":1752233059000,"contributors":[{"name":"Dev-Liz","username":"Dev-Liz","email":"basseyelizabeth569@gmail.com","commits":2,"url":"https://github.com/Dev-Liz"}],"changelog":[{"hash":"0acba5225b3b7241742c11f2eb31ec2dcd6ddd05","time":1752233059000,"email":"basseyelizabeth569@gmail.com","author":"Dev-Liz","message":"Updated content"},{"hash":"a6376b6867019658f19d5f27afd0cae5c3b98baa","time":1751456764000,"email":"basseyelizabeth569@gmail.com","author":"Dev-Liz","message":"updated docs"}]},"filePathRelative":"tutorials/fundamentals/data-types.md"}');export{l as comp,r as data};
